import Image from 'next/image';
import { cn } from '@/lib/utils';

/**
 * Decorative art generated by scripts/generate_stickers.py (Pillow). Dimensions
 * are the files' intrinsic pixel sizes so next/image can reserve space (no
 * layout shift); `size` below sets the *displayed* width.
 */
export const STICKER_FILES = {
  teddy: { src: '/stickers/teddy.png', w: 336, h: 336 },
  bunny: { src: '/stickers/bunny-headphones.png', w: 336, h: 336 },
  heart: { src: '/stickers/heart-green.png', w: 188, h: 188 },
  star: { src: '/stickers/star-sage.png', w: 140, h: 140 },
  envelope: { src: '/stickers/envelope.png', w: 172, h: 132 },
  waveform: { src: '/stickers/waveform.png', w: 220, h: 70 },
  cat: { src: '/stickers/pixel-cat.png', w: 120, h: 96 },
  pixelHeart: { src: '/stickers/pixel-heart-sage.png', w: 66, h: 60 },
  pixelHeartForest: { src: '/stickers/pixel-heart-forest.png', w: 66, h: 60 },
  pixelHeartWhite: { src: '/stickers/pixel-heart-white.png', w: 66, h: 60 },
  sparkle: { src: '/stickers/sparkle-sage.png', w: 64, h: 64 },
  folderStar: { src: '/stickers/folder-star.png', w: 152, h: 128 },
} as const;

export type StickerName = keyof typeof STICKER_FILES;

type Props = {
  name: StickerName;
  /** Displayed width in px. */
  size: number;
  className?: string;
  /** Gentle idle float. Stops under prefers-reduced-motion (motion-ambient). */
  float?: boolean;
  /** Rotation in degrees, also used as the hover-pop direction. */
  rotate?: number;
  /** Pixel art must not be smoothed when scaled. */
  pixel?: boolean;
};

/** A purely decorative sticker: aria-hidden, non-interactive, absolutely
 *  positioned by the caller via `className`. Never carries content. */
export function Sticker({ name, size, className, float = false, rotate = 0, pixel = false }: Props) {
  const file = STICKER_FILES[name];
  return (
    <span
      aria-hidden="true"
      className={cn(
        'sticker-pop pointer-events-none absolute select-none',
        float && 'motion-ambient animate-float-slow',
        className
      )}
      style={{ width: size, rotate: `${rotate}deg`, ['--pop-rot' as string]: `${rotate * -1 || -4}deg` }}
    >
      <Image
        src={file.src}
        alt=""
        width={file.w}
        height={file.h}
        sizes={`${size}px`}
        className={cn('h-auto w-full', pixel && '[image-rendering:pixelated]')}
        draggable={false}
      />
    </span>
  );
}
